/* U: доступность: у каждой sl-icon-button есть label (из tooltip/title/имени иконки), на странице есть h1. API NOXua11y */
(function(){ if(window.NOXua11y)return;
 const RU={x:'Закрыть','chevron-left':'Свернуть','chevron-right':'Развернуть','chevron-down':'Раскрыть','chevron-up':'Свернуть',plus:'Добавить',minus:'Убрать',trash:'Удалить',pencil:'Править',edit:'Править',copy:'Копировать',search:'Поиск',settings:'Настройки',refresh:'Обновить',download:'Скачать',upload:'Загрузить','arrow-up':'Вверх','arrow-down':'Вниз','arrow-left':'Назад','arrow-right':'Вперёд','zoom-in':'Увеличить','zoom-out':'Уменьшить',lock:'Заблокировать','lock-open':'Разблокировать',eye:'Показать','eye-off':'Скрыть',bell:'Уведомления',star:'Избранное',menu:'Меню','dots':'Ещё','dots-vertical':'Ещё',palette:'Палитра',brush:'Кисть',eraser:'Ластик',square:'Прямоугольник',circle:'Круг',line:'Линия',pointer:'Выбор','hand-stop':'Рука','arrow-back-up':'Отменить','arrow-forward-up':'Повторить','rotate':'Повернуть','rotate-clockwise':'Повернуть','rotate-2':'Повернуть',microphone:'Микрофон',paperclip:'Вложить',send:'Отправить','player-play':'Играть','player-pause':'Пауза','player-stop':'Стоп',check:'Готово','align-left':'По левому краю','align-center':'По центру','align-right':'По правому краю',layers:'Слои',photo:'Изображение',text:'Текст',typography:'Текст',pin:'Закрепить',history:'История'};
 function lab(e){const n=e.getAttribute('name')||'';const tt=e.closest('sl-tooltip');return e.getAttribute('label')||e.getAttribute('aria-label')||(tt&&tt.getAttribute('content'))||e.getAttribute('title')||e.getAttribute('data-ds-title')||RU[n]||(n?n.replace(/-/g,' '):'Кнопка')}
 function fix(){let c=0;document.querySelectorAll('sl-icon-button').forEach(function(e){if(e.getAttribute('label')&&e.getAttribute('label').trim())return;e.setAttribute('label',lab(e));c++});
  if(!document.querySelector('h1')){const h=document.createElement('h1');h.textContent=(document.title||'NOX').replace(/\s*[·|—-].*$/,'').trim()||'NOX';h.style.cssText='position:absolute;width:1px;height:1px;margin:-1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap;border:0;padding:0';(document.querySelector('main,#page')||document.body).prepend(h)}
  return c}
 let t;const later=function(){clearTimeout(t);t=setTimeout(fix,200)};
 function init(){fix();try{new MutationObserver(later).observe(document.body,{childList:true,subtree:true})}catch(e){}setTimeout(fix,1500);setTimeout(fix,4000)}
 if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init);else init();
 window.NOXua11y={fix:fix};
})();
